import{c as a,Q as e,j as r,m as o}from"./chunks/framework.CHJbb1iY.js";const d="/my-knowledge/assets/%E7%BD%91%E7%BB%9C%E9%80%9A%E4%BF%A1.DdtWkYZe.png",l="/my-knowledge/assets/%E7%BD%91%E7%BB%9C.DOVVYEmM.png",s="/my-knowledge/assets/IP%E5%9C%B0%E5%9D%80.CVLSPUNO.png",n="/my-knowledge/assets/IPV4.Dd-s_oBQ.png",i="/my-knowledge/assets/IPV4%20%E7%9A%84%E5%9C%B0%E5%9D%80%E5%88%86%E7%B1%BB.CehCnlwL.png",h="/my-knowledge/assets/IPV4%E5%9C%B0%E5%9D%80%E8%8C%83%E5%9B%B4.BXt9QHJc.png",p="/my-knowledge/assets/%E5%9F%9F%E5%90%8D%E4%B8%8E%E7%AB%AF%E5%8F%A3.C3lwP9sC.png",c="/my-knowledge/assets/%E7%AB%AF%E5%8F%A3%E7%90%86%E8%A7%A3.UAydkd3E.png",u="/my-knowledge/assets/%E7%BD%91%E7%BB%9C%E9%80%9A%E4%BF%A1%E5%8D%8F%E8%AE%AE.CBOdoS6Y.png",g="/my-knowledge/assets/TCP%E5%92%8CUDP.YxAbxIEZ.png",E=JSON.parse('{"title":"","description":"","frontmatter":{"aside":"right","outline":[2,3]},"headers":[],"relativePath":"docs/Java/第三阶段/网络编程/98.网络的基本概念.md","filePath":"docs/Java/第三阶段/网络编程/98.网络的基本概念.md"}'),b={name:"docs/Java/第三阶段/网络编程/98.网络的基本概念.md"};function P(_,t,m,q,f,x){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 style="text-align:center;font-weight:bold;">网络的基本概念</h1><hr><h2 id="_1-网络通信" tabindex="-1">1. 网络通信 <a class="header-anchor" href="#_1-网络通信" aria-label="Permalink to &quot;1. 网络通信&quot;">​</a></h2><h4 id="简单来说-网络通信就是数据的传输" tabindex="-1">简单来说：网络通信就是<span style="color:red;font-weight:bold;">数据的传输</span> <a class="header-anchor" href="#简单来说-网络通信就是数据的传输" aria-label="Permalink to &quot;简单来说：网络通信就是&lt;span style = &quot;color:red;font-weight:bold&quot;&gt;数据的传输&lt;/span&gt;&quot;">​</a></h4><p><img src="'+d+'" alt="alt text"></p><h2 id="_2-网络" tabindex="-1">2. 网络 <a class="header-anchor" href="#_2-网络" aria-label="Permalink to &quot;2. 网络&quot;">​</a></h2><h3 id="_1-局域网" tabindex="-1">（1）局域网 <a class="header-anchor" href="#_1-局域网" aria-label="Permalink to &quot;（1）局域网&quot;">​</a></h3><h4 id="覆盖范围最小-仅仅覆盖一个教室或一个机房" tabindex="-1">覆盖范围最小，仅仅覆盖一个教室或一个机房 <a class="header-anchor" href="#覆盖范围最小-仅仅覆盖一个教室或一个机房" aria-label="Permalink to &quot;覆盖范围最小，仅仅覆盖一个教室或一个机房&quot;">​</a></h4><h3 id="_2-城域网" tabindex="-1">（2）城域网 <a class="header-anchor" href="#_2-城域网" aria-label="Permalink to &quot;（2）城域网&quot;">​</a></h3><h4 id="覆盖范围较大-可以覆盖一个城市" tabindex="-1">覆盖范围较大，可以覆盖一个城市 <a class="header-anchor" href="#覆盖范围较大-可以覆盖一个城市" aria-label="Permalink to &quot;覆盖范围较大，可以覆盖一个城市&quot;">​</a></h4><h3 id="_3-广域网" tabindex="-1">（3）广域网 <a class="header-anchor" href="#_3-广域网" aria-label="Permalink to &quot;（3）广域网&quot;">​</a></h3><h4 id="覆盖范围最大-可以覆盖全国-甚至全球-万维网是广域网的代表" tabindex="-1">覆盖范围最大，可以覆盖全国，甚至全球，<span style="color:red;font-weight:bold;">万维网是广域网的代表</span> <a class="header-anchor" href="#覆盖范围最大-可以覆盖全国-甚至全球-万维网是广域网的代表" aria-label="Permalink to &quot;覆盖范围最大，可以覆盖全国，甚至全球，&lt;span style = &quot;color:red;font-weight:bold&quot;&gt;万维网是广域网的代表&lt;/span&gt;&quot;">​</a></h4><p><img src="'+l+'" alt="alt text"></p><h2 id="_3-ip-地址" tabindex="-1">3. IP 地址 <a class="header-anchor" href="#_3-ip-地址" aria-label="Permalink to &quot;3. IP 地址&quot;">​</a></h2><h4 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h4><ul><li><span style="color:red;font-weight:bold;">IP 地址（192.168.16.69） = 网络地址（192.168.16） + 主机地址（69）</span></li><li>IPV6：由于 IPV4 能表示的<strong>网络地址资源</strong>，引入了 IPV6，能够表示更多的网络地址资源</li></ul><p><img src="'+s+'" alt="alt text"></p><h3 id="_1-ipv4" tabindex="-1">（1）IPV4 <a class="header-anchor" href="#_1-ipv4" aria-label="Permalink to &quot;（1）IPV4&quot;">​</a></h3><h4 id="说明-1" tabindex="-1">说明 <a class="header-anchor" href="#说明-1" aria-label="Permalink to &quot;说明&quot;">​</a></h4><ul><li><p>一个字节 = 8 个 bit 位（一个 bit 就表示二进制的一位）</p></li><li><p>一个字节的范围：<strong>0(00000000) ~ 255(11111111)</strong></p><ul><li>0 的计算：0 × 2<sup>7</sup> + 0 × 2<sup>6</sup> + 0 × 2<sup>5</sup> + 0 × 2<sup>4</sup> + 0 × 2<sup>3</sup> + 0 × 2<sup>2</sup> + 0 × 2<sup>1</sup> + 0 × 2<sup>0</sup> = 0</li><li>255 的计算：1 × 2<sup>7</sup> + 1 × 2<sup>6</sup> + 1 × 2<sup>5</sup> + 1 × 2<sup>4</sup> + 1 × 2<sup>3</sup> + 1 × 2<sup>2</sup> + 1 × 2<sup>1</sup> + 1 × 2<sup>0</sup> = 128 + 64 + 32 + 16 + 8 + 4 + 2 + 1 = 255</li></ul></li><li><p>IPV4 有<span style="color:red;font-weight:bold;">4 个字节 = 32 个 bit 位</span></p></li><li><p><span style="color:red;font-weight:bold;">地址</span>是以<span style="color:red;font-weight:bold;">十进制</span>来表示的</p></li></ul><p><img src="'+n+'" alt="alt text"></p><h3 id="_1-ipv4-的地址分类" tabindex="-1">1. IPV4 的地址分类 <a class="header-anchor" href="#_1-ipv4-的地址分类" aria-label="Permalink to &quot;1. IPV4 的地址分类&quot;">​</a></h3><p><img src="'+i+'" alt="alt text"></p><h3 id="_2-ipv4-表示地址的范围" tabindex="-1">2. IPV4 表示地址的范围 <a class="header-anchor" href="#_2-ipv4-表示地址的范围" aria-label="Permalink to &quot;2. IPV4 表示地址的范围&quot;">​</a></h3><p><img src="'+h+'" alt="alt text"></p><h3 id="_2-ipv6" tabindex="-1">（2）IPV6 <a class="header-anchor" href="#_2-ipv6" aria-label="Permalink to &quot;（2）IPV6&quot;">​</a></h3><ul><li>使用<span style="color:red;font-weight:bold;">16 个字节（128（16 x 8）个 bit 位）</span>，是 IPV4 的<span style="color:red;font-weight:bold;">4 倍</span></li><li><span style="color:red;font-weight:bold;">地址</span>是以<span style="color:red;font-weight:bold;">十六进制</span>来表示的</li><li>例如：<strong>2408.8207.1851.8670.d52d.7a14.362c.4e8d</strong></li></ul><h4 id="进制内容补充" tabindex="-1">进制内容补充 <a class="header-anchor" href="#进制内容补充" aria-label="Permalink to &quot;进制内容补充&quot;">​</a></h4><ul><li><strong>2<sup>4</sup> = 16</strong>，也就是说 <span style="color:red;font-weight:bold;">16 进制中的 1 位对应 2 进制中的 4 位</span></li><li>根据上面的 IP 地址，每 4 位（<strong>每一位是十六进制中的一位</strong>）一组，一共 8 组，也就是一共<strong>4 * 8 = 32</strong>位（16 进制）</li><li>那根据关系可以知道，<span style="color:red;font-weight:bold;">1 位（16 进制） = 4 位（2 进制）</span>，则一共对应 2 进制的位数：<strong>32 * 4 = 128（2 进制）</strong></li><li>二进制中，<strong>每 8 位代表代表一个字节</strong>，现在是 128 / 8 = <strong>16 个字节</strong></li></ul><h2 id="_4-域名与端口" tabindex="-1">4. 域名与端口 <a class="header-anchor" href="#_4-域名与端口" aria-label="Permalink to &quot;4. 域名与端口&quot;">​</a></h2><p><img src="'+p+'" alt="alt text"></p><h3 id="_1-对端口的理解" tabindex="-1">1. 对端口的理解 <a class="header-anchor" href="#_1-对端口的理解" aria-label="Permalink to &quot;1. 对端口的理解&quot;">​</a></h3><p>一个服务器对应一个 ip，<span style="color:red;font-weight:bold;">服务器上可以有很多服务</span>，当程序向服务器发送请求时，就可以通过服务监听的端口来接收程序的请求，简单来说，<span style="color:red;font-weight:bold;">端口可以说是某项特定服务的标识</span>，当程序在服务器上请求服务时，可以通过端口来区分不同的服务</p><p><img src="'+c+'" alt="alt text"></p><h4 id="可以把服务器理解为房子-那端口-服务就可以理解为门-通过不同的门-不同的端口对应不同的服务-进入来访问不同的服务-程序发送请求-向哪个端口发送请求呢-进而就形象的解释了端口的作用" tabindex="-1">可以把服务器理解为房子，那端口 + 服务就可以理解为门，通过不同的门（<span style="color:red;font-weight:bold;">不同的端口对应不同的服务</span>）进入来访问不同的服务（程序发送请求，向哪个端口发送请求呢？），进而就形象的解释了端口的作用 <a class="header-anchor" href="#可以把服务器理解为房子-那端口-服务就可以理解为门-通过不同的门-不同的端口对应不同的服务-进入来访问不同的服务-程序发送请求-向哪个端口发送请求呢-进而就形象的解释了端口的作用" aria-label="Permalink to &quot;可以把服务器理解为房子，那端口 + 服务就可以理解为门，通过不同的门（&lt;span style = &quot;color:red;font-weight:bold&quot;&gt;不同的端口对应不同的服务&lt;/span&gt;）进入来访问不同的服务（程序发送请求，向哪个端口发送请求呢？），进而就形象的解释了端口的作用&quot;">​</a></h4><h3 id="_2-常见的端口" tabindex="-1">2. 常见的端口 <a class="header-anchor" href="#_2-常见的端口" aria-label="Permalink to &quot;2. 常见的端口&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>协议/服务</strong></th><th><strong>端口号</strong></th><th><strong>描述</strong></th></tr></thead><tbody><tr><td>SSH</td><td>22</td><td>用于安全远程登录</td></tr><tr><td>FTP</td><td>21</td><td>用于文件传输协议</td></tr><tr><td>SMTP</td><td>25</td><td>用于邮件发送（简单邮件传输协议）</td></tr><tr><td>HTTP</td><td>80</td><td>用于 HTTP 服务（无加密的网页浏览）</td></tr><tr><td>HTTPS</td><td>443</td><td>用于 HTTPS 服务（加密的网页浏览）</td></tr><tr><td>MySQL, MariaDB</td><td>3306</td><td>用于 MySQL 和 MariaDB 数据库</td></tr><tr><td>Tomcat (HTTP)</td><td>8080</td><td>用于 Tomcat 服务器的 HTTP 服务</td></tr><tr><td>Tomcat (HTTPS)</td><td>8443</td><td>用于 Tomcat 服务器的 HTTPS 服务</td></tr><tr><td>Redis</td><td>6379</td><td>用于 Redis 数据库服务</td></tr><tr><td>RabbitMQ</td><td>5672</td><td>用于 RabbitMQ 消息队列服务</td></tr><tr><td>MongoDB</td><td>27017</td><td>用于 MongoDB 数据库</td></tr><tr><td>Elasticsearch</td><td>9200</td><td>用于 Elasticsearch 搜索引擎服务</td></tr><tr><td>Jenkins</td><td>8080</td><td>用于 Jenkins 持续集成工具</td></tr><tr><td>Nginx</td><td>80, 443</td><td>用于 Nginx 反向代理和负载均衡服务</td></tr><tr><td>Git</td><td>9418</td><td>用于 Git 协议（版本控制工具）</td></tr><tr><td>Oracle</td><td>1521</td><td>用于 Oracle 数据库服务</td></tr><tr><td>SQL Server</td><td>1433</td><td>用于 SQL Server 数据库服务</td></tr></tbody></table><h3 id="_3-提醒" tabindex="-1">3. 提醒 <a class="header-anchor" href="#_3-提醒" aria-label="Permalink to &quot;3. 提醒&quot;">​</a></h3><h4 id="在实际开发中不要使用-0-1024端口" tabindex="-1">在实际开发中<span style="color:red;font-weight:bold;">不要使用 0 ~ 1024</span>端口 <a class="header-anchor" href="#在实际开发中不要使用-0-1024端口" aria-label="Permalink to &quot;在实际开发中&lt;span style = &quot;color:red;font-weight:bold&quot;&gt;不要使用 0 ~ 1024&lt;/span&gt;端口&quot;">​</a></h4><h2 id="_5-网络通信协议" tabindex="-1">5. 网络通信协议 <a class="header-anchor" href="#_5-网络通信协议" aria-label="Permalink to &quot;5. 网络通信协议&quot;">​</a></h2><p>协议 (tcp/ip) TCP/IP (Transmission Control Protocol/Internet Protocol) 的简写，中文译名为<strong>传输控制协议 / 因特网互联协议</strong>，又叫网络通讯协议，这个协议是 Internet 最基本的协议、Internet 国际互联网络的基础，简单地说，就是由网络层的 IP 协议和传输层的 TCP 协议组成的。</p><table><thead><tr><th>OSI模型</th><th>TCP/IP模型</th><th>TCP/IP模型各层对应协议</th></tr></thead><tbody><tr><td>应用层</td><td rowspan="3">应用层</td><td rowspan="3">HTTP、ftp、telnet、DNS...</td></tr><tr><td>表示层</td></tr><tr><td>会话层</td></tr><tr><td>传输层</td><td>传输层（TCP）</td><td rowspan="2">TCP、UDP、...<br>IP、ICMP、ARP...</td></tr><tr><td>网络层</td><td>网络层（IP）</td></tr><tr><td>数据链路层</td><td rowspan="2">物理+数据链路层</td><td rowspan="2">Link</td></tr><tr><td>物理层</td></tr></tbody></table><h4 id="数据在传输的过程中就是封装信息和拆包的过程" tabindex="-1">数据在传输的过程中就是封装信息和拆包的过程 <a class="header-anchor" href="#数据在传输的过程中就是封装信息和拆包的过程" aria-label="Permalink to &quot;数据在传输的过程中就是封装信息和拆包的过程&quot;">​</a></h4><ul><li>左边<strong>从上到下</strong>：发送数据，进行封装</li><li>右边<strong>从下到上</strong>：拆包，接收数据</li></ul><p><img src="'+u+'" alt="alt text"></p><h2 id="_6-tcp-和-udp" tabindex="-1">6. TCP 和 UDP <a class="header-anchor" href="#_6-tcp-和-udp" aria-label="Permalink to &quot;6. TCP 和 UDP&quot;">​</a></h2><h4 id="tcp-的三次握手就是确认双方的过程-经过确认后才会发送数据-这样更安全可靠" tabindex="-1">TCP 的<span style="color:red;font-weight:bold;">三次握手</span>就是确认双方的过程，经过确认后才会发送数据，这样更安全可靠 <a class="header-anchor" href="#tcp-的三次握手就是确认双方的过程-经过确认后才会发送数据-这样更安全可靠" aria-label="Permalink to &quot;TCP 的&lt;span style = &quot;color:red;font-weight:bold&quot;&gt;三次握手&lt;/span&gt;就是确认双方的过程，经过确认后才会发送数据，这样更安全可靠&quot;">​</a></h4><p><img src="'+g+'" alt="alt text"></p>',48)])])}const T=a(b,[["render",P]]);export{E as __pageData,T as default};
